WITH unpacked AS (SELECT id, currency, tier_prices, discounts, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT currency, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, COUNT(DISTINCT id) AS distinct_ids, SIZE(COLLECT_SET(currency)) AS num_currencies, COUNT_IF(currency = 'USD') AS usd_events, COUNT(DISTINCT currency) AS distinct_currencies, ROUND(SUM(entry_price) / NULLIF(COUNT(CASE WHEN currency = 'THB' THEN 1 END), 0), 2) AS entry_price_per_thb FROM unpacked GROUP BY currency;
